package com.folha.pd2;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.webkit.*;import android.util.Base64;import android.view.*;import android.widget.Toast;import java.io.*;import java.util.*;
public class MainActivity extends Activity {
 private String incomingBase64,incomingName="documento-recebido.pdf";private Updater updater;private WebView web;private ValueCallback<Uri[]> picker;private byte[] pending;private static final String HOST="appassets.androidplatform.net";
 @Override public void onCreate(Bundle state){setTheme(initialDark()?android.R.style.Theme_Material_NoActionBar:android.R.style.Theme_Material_Light_NoActionBar);super.onCreate(state);updater=new Updater(this);getWindow().setStatusBarColor(0xff245e47);getWindow().setNavigationBarColor(0xfff8f9f5);web=new WebView(this);setContentView(web);
 if(Build.VERSION.SDK_INT>=35){web.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets b=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(b.left,b.top,b.right,b.bottom);return insets;});}
 WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setSupportMultipleWindows(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.addJavascriptInterface(new SaveBridge(),"Android");web.setWebViewClient(new WebViewClient(){
 @Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){Uri u=request.getUrl();if(!"https".equals(u.getScheme())||!HOST.equals(u.getHost()))return denied();String path=u.getPath();if(path==null||path.contains(".."))return denied();if(path.equals("/"))path="/index.html";try{String mime=path.endsWith(".js")?"application/javascript":path.endsWith(".css")?"text/css":path.endsWith(".html")?"text/html":path.endsWith(".wasm")?"application/wasm":"application/octet-stream";Map<String,String> h=new HashMap<>();h.put("Access-Control-Allow-Origin","*");return new WebResourceResponse(mime,"UTF-8",200,"OK",h,getAssets().open(path.substring(1)));}catch(IOException e){return new WebResourceResponse("text/plain","UTF-8",404,"Not Found",new HashMap<>(),new ByteArrayInputStream(new byte[0]));}}
 @Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !"https".equals(r.getUrl().getScheme())||!HOST.equals(r.getUrl().getHost());}
 });web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView w,ValueCallback<Uri[]> callback,FileChooserParams params){if(picker!=null)picker.onReceiveValue(null);picker=callback;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");String[] accept=params.getAcceptTypes();if(accept.length>0)i.putExtra(Intent.EXTRA_MIME_TYPES,accept);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);try{startActivityForResult(i,10);}catch(Exception e){picker.onReceiveValue(null);picker=null;toast("Nenhum seletor de arquivos disponível.");}return true;}});receivePdf(getIntent(),true);updater.automatic();}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);new AlertDialog.Builder(this).setTitle("Abrir PDF recebido?").setMessage("O documento será aberto nesta aba. Salve os resultados atuais antes de continuar.").setPositiveButton("Abrir",(d,w)->{setIntent(intent);receivePdf(intent,true);}).setNegativeButton("Cancelar",null).show();}
 private void receivePdf(Intent intent,boolean reload){
  String action=intent==null?null:intent.getAction();
  Uri uri=null;if(Intent.ACTION_VIEW.equals(action))uri=intent.getData();else if(Intent.ACTION_SEND.equals(action))uri=intent.getParcelableExtra(Intent.EXTRA_STREAM);
  final Uri source=uri;
  if(source==null){web.loadUrl("https://"+HOST+"/index.html");return;}
  if(!"content".equals(source.getScheme())){toast("Abra o PDF pelo seletor de documentos do Android.");web.loadUrl("https://"+HOST+"/index.html");return;}
  new Thread(()->{
   try(InputStream in=getContentResolver().openInputStream(source);ByteArrayOutputStream out=new ByteArrayOutputStream()){
    if(in==null)throw new IOException("Documento indisponível.");byte[] chunk=new byte[32768];int n;
    while((n=in.read(chunk))!=-1){if(out.size()+n>50*1024*1024)throw new IOException("PDF maior que 50 MB.");out.write(chunk,0,n);}
    byte[] data=out.toByteArray();if(data.length<5||data[0]!='%'||data[1]!='P'||data[2]!='D'||data[3]!='F'||data[4]!='-')throw new IOException("O conteúdo recebido não é PDF.");
    String name="documento-recebido.pdf";
    try(android.database.Cursor c=getContentResolver().query(source,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}catch(Exception ignored){}
    incomingName=name==null?"documento-recebido.pdf":name;incomingBase64=Base64.encodeToString(data,Base64.NO_WRAP);
   }catch(Exception e){incomingBase64=null;toast("Não foi possível receber o PDF: "+e.getMessage());}
   runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())web.loadUrl("https://"+HOST+"/index.html");});
  }).start();
 }
 private WebResourceResponse denied(){return new WebResourceResponse("text/plain","UTF-8",403,"Forbidden",new HashMap<>(),new ByteArrayInputStream(new byte[0]));}
 private void toast(String s){runOnUiThread(()->Toast.makeText(this,s,Toast.LENGTH_LONG).show());}
 private boolean systemDark(){return (getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK)==android.content.res.Configuration.UI_MODE_NIGHT_YES;}
 private boolean initialDark(){String mode=getSharedPreferences("appearance",0).getString("theme","system");return "dark".equals(mode)||"system".equals(mode)&&systemDark();}
 public class SaveBridge{
 @JavascriptInterface public String getVersionName(){try{return getPackageManager().getPackageInfo(getPackageName(),0).versionName;}catch(Exception e){return "desconhecida";}}
 @JavascriptInterface public synchronized String takeIncomingBase64(){String value=incomingBase64;incomingBase64=null;return value;}
 @JavascriptInterface public String getIncomingName(){return incomingName;}
 @JavascriptInterface public boolean isSystemDark(){return systemDark();}
 @JavascriptInterface public void setThemeMode(String mode,boolean dark){if(!"system".equals(mode)&&!"light".equals(mode)&&!"dark".equals(mode))return;getSharedPreferences("appearance",0).edit().putString("theme",mode).apply();runOnUiThread(()->{setTheme(dark?android.R.style.Theme_Material_NoActionBar:android.R.style.Theme_Material_Light_NoActionBar);getWindow().setStatusBarColor(dark?0xff141d18:0xff245e47);getWindow().setNavigationBarColor(dark?0xff141d18:0xfff8f9f5);int flags=getWindow().getDecorView().getSystemUiVisibility();flags&=~(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);if(!dark)flags|=View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR;getWindow().getDecorView().setSystemUiVisibility(flags);web.setBackgroundColor(dark?0xff141d18:0xfff8f9f5);});}

 @JavascriptInterface public void openUpdates(){runOnUiThread(()->updater.menu());}
 @JavascriptInterface public void shareFile(String name,String data,String mime){new Thread(()->{try{File dir=new File(getCacheDir(),"exports");dir.mkdirs();String safe=name.replaceAll("[^A-Za-z0-9_.-]","_");if(safe.length()>100)safe=safe.substring(safe.length()-100);File file=new File(dir,System.currentTimeMillis()+"-"+safe);try(FileOutputStream out=new FileOutputStream(file)){out.write(Base64.decode(data,Base64.DEFAULT));}Uri uri=Uri.parse("content://"+getPackageName()+".files/"+file.getName());runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_SEND);i.setType(mime);i.putExtra(Intent.EXTRA_STREAM,uri);i.setClipData(ClipData.newRawUri("Documento",uri));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivity(Intent.createChooser(i,"Compartilhar documento"));}catch(Exception e){toast("Não há aplicativo para compartilhar este arquivo.");}});}catch(Exception e){toast("Não foi possível preparar o compartilhamento.");}}).start();}
@JavascriptInterface public void saveFile(String name,String data,String mime){try{if(pending!=null){toast("Conclua o salvamento anterior primeiro.");return;}pending=Base64.decode(data,Base64.DEFAULT);runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(mime);i.putExtra(Intent.EXTRA_TITLE,name);try{startActivityForResult(i,11);}catch(Exception e){pending=null;toast("Não foi possível abrir o salvamento.");}});}catch(Exception e){pending=null;toast("Não foi possível preparar o arquivo para salvar.");}}}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==12){if(getPackageManager().canRequestPackageInstalls())updater.install();return;}if(req==10){if(picker==null)return;List<Uri> uris=new ArrayList<>();if(result==RESULT_OK&&data!=null){if(data.getClipData()!=null){for(int n=0;n<data.getClipData().getItemCount();n++)uris.add(data.getClipData().getItemAt(n).getUri());}else if(data.getData()!=null)uris.add(data.getData());}picker.onReceiveValue(uris.isEmpty()?null:uris.toArray(new Uri[0]));picker=null;}if(req==11){byte[] bytes=pending;pending=null;if(result==RESULT_OK&&data!=null&&data.getData()!=null&&bytes!=null){Uri uri=data.getData();new Thread(()->{try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException();out.write(bytes);toast("Arquivo salvo com sucesso.");}catch(Exception e){toast("Não foi possível salvar o arquivo. Tente outro local.");}}).start();}else toast("Salvamento cancelado. Você pode tentar novamente.");}}
 @Override public void onBackPressed(){new AlertDialog.Builder(this).setTitle("Sair do Folha PDF?").setMessage("Os arquivos ainda não salvos serão descartados.").setPositiveButton("Sair",(d,w)->finish()).setNegativeButton("Continuar",null).show();}
 @Override protected void onDestroy(){if(picker!=null)picker.onReceiveValue(null);web.removeJavascriptInterface("Android");web.destroy();super.onDestroy();}
}
